def estimate_pretraining(n_params, n_tokens=None):
    chinchilla_tokens = 20 * n_params
    used_tokens = chinchilla_tokens if n_tokens is None else n_tokens
    flops = 6 * n_params * used_tokens
    train_mem_gb = n_params * 16 / 1e9
    return {
        "flops": flops,
        "chinchilla_tokens": chinchilla_tokens,
        "train_mem_gb": train_mem_gb,
    }
